ee:message.ee:set-payload:
%dw 2.0
output application/json

var TOP_N = 5
var weights = {
    service_description: 0.30,
    summary_notes: 0.30,
    problem_description: 0.20,
    material_description: 0.20
}

// Combine all route payloads
var allCalls = (vars.problemResults default []) ++ 
               (vars.serviceResults default []) ++ 
               (vars.summaryResults default []) ++ 
               (vars.materialResults default [])

// Helper function to split materials by ';' or '|'
fun parseMaterials(desc) = 
    if (desc == null or upper(trim(desc)) == "NULL" or trim(desc) == "") []
    else if (desc contains ";") (desc splitBy ";") map trim($) filter (!isEmpty($))
    else if (desc contains "|") (desc splitBy "|") map trim($) filter (!isEmpty($))
    else [trim(desc)]

// Expand calls to individual materials, multiply by channel weight
var flattenedMaterials = flatten(
    allCalls map ((call) -> 
        parseMaterials(call.material_description) map ((mat) -> {
            material: mat,
            weightedScore: call.similarity_score * (weights[call.search_channel] default 1.0)
        })
    )
)

// Group by exact material text and sum the scores
var groupedMaterials = flattenedMaterials groupBy $.material
var aggregatedScores = groupedMaterials mapObject ((items, mat) -> {
    (mat): sum(items map $.weightedScore)
})

// Convert to array, sort descending, limit to TOP_N
var rankedArray = (keysOf(aggregatedScores) map ((mat) -> {
    similarity_score: ((aggregatedScores[mat] as Number) * 10000) roundBy 0 / 10000,
    material_details: {
        ITEMDESC: mat as String
    }
})) orderBy -$.similarity_score

---
{
    Service_Call_ID: vars.targetId,
    search_metadata: {
        search_mode: "four_channel",
        target_division: vars.targetDivision,
        similar_calls_considered: sizeOf(allCalls),
        total_suggestions_found: sizeOf(rankedArray),
        channel_weights: weights,
        hits_per_channel: {
            problem_description: sizeOf(vars.problemResults default []),
            service_description: sizeOf(vars.serviceResults default []),
            summary_notes: sizeOf(vars.summaryResults default []),
            material_description: sizeOf(vars.materialResults default [])
        }
    },
    suggested_materials: rankedArray[0 to (TOP_N - 1)] default []
}
